json') as f:\n    data = json.load(f)\n\n# The data might be embedded in a figure description or in an unexpected place\n# Let's look at ALL elements that have any numeric data for 2004-2006 and quarters\nfor i, elem in enumerate(data['document']['elements']):\n    content = str(elem.get('content', ''))\n    if ('2004' in content or '2005' in content or '2006' in content) and ('Mar' in content or 'June' in content or 'Q1' in content or 'Q2' in content):\n        # Also check for nonfarm or related terms\n        if 'employ' in content.lower() or 'payroll' in content.lower() or 'labor' in content.lower() or 'thousand' in content.lower():\n            print(f\\\"Index: {i}, Type: {elem['type']}\\\")\n            print(f\\\"Content: {content[:1500]}\\\")\n            print('---')\n\""}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
